import { mkdirSync, writeFileSync } from "fs";
import { join } from "path";

export const DEFAULT_INTERVAL = "1h";
export const DEFAULT_MAX_TICK = "10m";

export type RoutineInput = {
  slug: string;
  prompt: string;
  skillsRun: string[];
  skillsRefer: string[];
  mcpUrl: string;
  interval?: string;
  maxTick?: string;
};

export function harnessRoot(home: string): string {
  return join(home, ".dora", "harness");
}

export function routineDir(home: string, slug: string): string {
  return join(harnessRoot(home), slug);
}

function yamlList(key: string, items: string[]): string {
  if (items.length === 0) return `${key}: []`;
  return `${key}:\n${items.map((s) => `  - ${s}`).join("\n")}`;
}

export function writeRoutine(home: string, input: RoutineInput): string {
  const dir = routineDir(home, input.slug);
  mkdirSync(dir, { recursive: true });
  const prompt = input.prompt.endsWith("\n") ? input.prompt : input.prompt + "\n";
  writeFileSync(join(dir, "prompt.md"), prompt);
  writeFileSync(
    join(dir, "routine.yml"),
    [
      yamlList("skills_run", input.skillsRun),
      yamlList("skills_refer", input.skillsRefer),
      `mcp_url: ${input.mcpUrl}`,
      `interval: ${input.interval ?? DEFAULT_INTERVAL}`,
      `max_tick: ${input.maxTick ?? DEFAULT_MAX_TICK}`,
      "",
    ].join("\n"),
  );
  return dir;
}

