export function defaultOpenDir(dir: string): void {
  const cmd = process.platform === "darwin" ? "open" : process.platform === "win32" ? "explorer" : "xdg-open";
  spawnSync([cmd, dir], { stdout: "ignore", stderr: "ignore" });
}

